import{_ as e,o as a,c as t,ae as l}from"./chunks/framework.FQ5RHm_v.js";const m=JSON.parse('{"title":"wvke-sdk | Personalizzazione Perfetta!","titleTemplate":false,"description":"","frontmatter":{"title":"wvke-sdk | Personalizzazione Perfetta!","titleTemplate":false},"headers":[],"relativePath":"it/index.md","filePath":"it/index.md"}'),o={name:"it/index.md"};function r(n,i,s,d,p,c){return a(),t("div",null,[...i[0]||(i[0]=[l('<h1 id="wvke-sdk" tabindex="-1">wvke-sdk <a class="header-anchor" href="#wvke-sdk" aria-label="Permalink to &quot;wvke-sdk&quot;">​</a></h1><p>wvke-sdk è un SDK JavaScript per comunicare con periferiche gaming, inclusi tastiere e mouse.</p><p>Costruito sulla moderna tecnologia WebHID, consente la personalizzazione profonda e il controllo intelligente di tastiere, mouse e altre periferiche. Accelera la consegna end-to-end dei prodotti periferiche gaming e apre nuove possibilità nell&#39;ecosistema gaming. Il progetto è sviluppato e mantenuto dal GDE Game Driver Engine Team.</p><h2 id="tipi-di-sdk" tabindex="-1">Tipi di SDK <a class="header-anchor" href="#tipi-di-sdk" aria-label="Permalink to &quot;Tipi di SDK&quot;">​</a></h2><h3 id="⌨️-tastiera-lineare" tabindex="-1">⌨️ Tastiera Lineare <a class="header-anchor" href="#⌨️-tastiera-lineare" aria-label="Permalink to &quot;⌨️ Tastiera Lineare&quot;">​</a></h3><p>Costruita per tastiere meccaniche:</p><ul><li>Mappatura dei tasti e cambio livello</li><li>Controllo illuminazione RGB</li><li>Autorizzazione WebHID, elenco dispositivi autorizzati e inizializzazione</li><li>Interruttore a corsa completa RT, regolazione corsa e zona di sicurezza</li><li>Registrazione e riproduzione di macro</li><li>Regolazione frequenza di polling (1KHz-8KHz)</li><li>Cambio modalità sistema (Windows/Mac)</li></ul><h3 id="🖱️-sdk-mouse" tabindex="-1">🖱️ SDK Mouse <a class="header-anchor" href="#🖱️-sdk-mouse" aria-label="Permalink to &quot;🖱️ SDK Mouse&quot;">​</a></h3><p>Costruito per mouse gaming:</p><ul><li>Regolazione DPI (400-16000 DPI)</li><li>Programmazione pulsanti e macro</li><li>Personalizzazione illuminazione RGB</li><li>Regolazione distanza di sollevamento</li><li>Ottimizzazione polling</li></ul><h2 id="caratteristiche" tabindex="-1">Caratteristiche <a class="header-anchor" href="#caratteristiche" aria-label="Permalink to &quot;Caratteristiche&quot;">​</a></h2><ul><li>Supporto moderno JavaScript/TypeScript</li><li>Comunicazione hardware WebHID</li><li>API complete per il controllo dell&#39;illuminazione</li><li>API per mappatura tasti e macro</li><li>API corsa RT, tasti avanzati e inizializzazione</li><li>API DPI e mappatura pulsanti mouse</li><li>Servizio di aggiornamento personalizzato generale</li><li>Documentazione API dettagliata</li></ul><h2 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wvke-sdk</span></span></code></pre></div><p>Consulta la <a href="/wvke.sdkdoc/docs/it/api/info.html">documentazione API</a> per maggiori dettagli.</p>',15)])])}const h=e(o,[["render",r]]);export{m as __pageData,h as default};
